  "steps": [
    {
      "id": 1,
      "claim": "Dualism is a theory in public international law that treats international law and domestic (municipal) law as separate legal orders.",
      "evidence": "Standard definitions in international law textbooks (e.g., Shaw, *International Law* 9th ed., p.124; Oppenheim, *International Law*).",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Under dualism, international law has no direct effect in the domestic legal system unless it is incorporated by legislation (the transformation doctrine).",
      "evidence": "Doctrine of transformation; case law such as *R v Secretary of State for the Home Department, ex parte Simms* (UK) and similar rulings in dualist states.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Dualism does not prescribe a hierarchy between the two systems; it merely asserts their distinctness.",
      "evidence": "Shaw, *International Law* 9th ed., p.124 notes that dualism maintains separation without assigning superiority, unlike monism which merges the orders.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Option B (‘Under dualism, international and domestic laws comprise distinct legal systems’) accurately captures the core dualist principle described in steps 1‑3.",
      "evidence": "The wording of option B matches the definition and consequences of dualism without adding incorrect qualifiers.",
      "weight": 0.10,
      "depends_on": [1, 2, 3]
    },
    {
      "id": 5,
      "claim": "Options A, C, and D each contain statements inconsistent with dualism.",
      "evidence": "A describes monism (unified system); C adds an unwarranted ‘equal in hierarchy’ claim not part of dualist doctrine; D overstates by saying domestic law always prevails, which dualism does not assert.",
      "weight": 0.10,
      "depends_on": [1, 3]
    }
  ],
  "answer": "B",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Describes monism, which posits a single unified legal system, contrary to dualist separation."
    },
    {
      "answer": "C",
      "reason_rejected": "Adds ‘equal in hierarchy’, a claim not part of the dualist definition."
    },
    {
      "answer": "D",
      "reason_rejected": "States domestic law always prevails, an absolute not supported by dualist theory."
    }
  ]
}
